export const BODY: string = "\n<p>مؤشرات الويب الأساسية هي نتائج السرعة التي تستخدمها جوجل للحكم على صفحاتك. تؤثر في ترتيبك في نتائج البحث وتجربة زوارك.</p>\n<p>الصور تؤثر في النتائج الثلاث كلها. صورة رئيسية ثقيلة تؤخر ظهور المحتوى، وصور دون أبعاد تحرك التخطيط، وملفات ثقيلة تبطئ التفاعل.</p>\n<p>يشرح هذا المقال كيف يحرك تحسين الصور كل نتيجة، وما الذي تصلحه أولًا.</p>\n<h2 id=\"what-are-cwv\">ما هي مؤشرات الويب الأساسية؟</h2>\n<p>مؤشرات الويب الأساسية ثلاثة: LCP يقيس سرعة ظهور أكبر عنصر، وCLS يقيس ثبات التخطيط، وINP يقيس سرعة استجابة الصفحة للتفاعل.</p>\n<p>جوجل تستخدم هذه النتائج عامل ترتيب. الصفحات السريعة والمستقرة تظهر أعلى في نتائج البحث، والبطيئة تتراجع.</p>\n<h2 id=\"lcp-explained\">LCP: لماذا تقرره الصورة الرئيسية؟</h2>\n<p>LCP هو الوقت الذي يستغرقه أكبر عنصر في الصفحة حتى يظهر. في معظم الصفحات، هذا العنصر هو الصورة الرئيسية.</p>\n<p>إذا كانت الصورة الرئيسية ثقيلة، تأخر ظهورها وتأخرت نتيجة LCP. لذلك تحسين الصورة الرئيسية هو أسرع طريق لتحسين LCP.</p>\n<h2 id=\"fixing-lcp\">كيف تصلح LCP بطيئًا خطوة بخطوة؟</h2>\n<p>لإصلاح LCP بطيء خطوة بخطوة: ابدأ بضغط الصورة الرئيسية إلى حجم مناسب، ثم حدد أبعادها، ثم أزل التحميل الكسول عنها.</p>\n<p>استخدم <a href=\"/ar/tahsin-suwar-al-web/\">محسّن صور الويب</a> لإعداد الصورة الرئيسية بشكل صحيح. بعدها قس النتيجة مجددًا بأداة قياس السرعة.</p>\n<h2 id=\"cls-explained\">CLS: كيف تحرك الصور التخطيط؟</h2>\n<p>CLS يقيس كم يتحرك التخطيط أثناء التحميل. الصور دون أبعاد محددة هي السبب الأول: تظهر الصورة فجأة فيدفع المحتوى للأسفل.</p>\n<p>الحل بسيط: حدد العرض والارتفاع في وسم كل صورة. المتصفح يحجز المساحة مسبقًا، فلا يتحرك التخطيط عند ظهور الصورة.</p>\n<h2 id=\"inp-explained\">INP: كيف يبطئ وزن الصورة التفاعل؟</h2>\n<p>INP يقيس سرعة استجابة الصفحة عندما ينقر الزائر أو يكتب. الصور الثقيلة تستهلك معالجة المتصفح، فيتأخر الرد على التفاعل.</p>\n<p>تقليل وزن الصور يحرر المعالجة للتفاعل. الصفحة الأخف تستجيب أسرع، ويشعر الزائر بأن الموقع أكثر سلاسة.</p>\n<h2 id=\"measuring-cwv\">كيف تقيس مؤشرات الويب الأساسية بشكل صحيح؟</h2>\n<p>قس مؤشرات الويب الأساسية بشكل صحيح بأدوات جوجل المجانية: PageSpeed Insights وSearch Console. الأولى تعطي تقريرًا فوريًا، والثانية تعرض بيانات حقيقية من الزوار.</p>\n<p>ركّز على بيانات الجوال أولًا. معظم الزوار يأتون من الهواتف، ونتائج الجوال أصعب في التحسين.</p>\n<h2 id=\"image-budgets\">كيف تحدد ميزانية صور لصفحة؟</h2>\n<p>حدد ميزانية صور لكل صفحة: مثلًا ميغابايت واحد كحد أقصى لجميع الصور. وزّع الميزانية: 200 كيلوبايت للصورة الرئيسية، و100 للصور العادية.</p>\n<p>الميزانية تمنع تراكم الصور الثقيلة مع الوقت. كل صورة جديدة يجب أن تناسب الميزانية قبل النشر.</p>\n<h2 id=\"formats-cwv\">الصيغ ومؤشرات الويب الأساسية</h2>\n<p>الصيغ تؤثر في المؤشرات: WebP أصغر من JPG، فيحمّل أسرع ويحسّن LCP. PNG كبير للصور الفوتوغرافية، فيضر بالنتائج.</p>\n<p>اختر الصيغة حسب نوع الصورة. الصيغة الصحيحة توفر كيلوبايتات دون فقدان جودة مرئية.</p>\n<h2 id=\"responsive-images\">الصور المتجاوبة وتغيير الدقة</h2>\n<p>الصور المتجاوبة تعني تقديم أحجام مختلفة لأجهزة مختلفة. الهاتف يحصل على صورة أصغر، والحاسوب يحصل على صورة أكبر.</p>\n<p>استخدم سمة srcset في وسم الصورة. المتصفح يختار الحجم المناسب لشاشة الزائر، فيوفر البيانات ويحسّن النتائج على الجوال.</p>\n<h2 id=\"common-cwv-mistakes\">أخطاء شائعة في مؤشرات الويب الأساسية</h2>\n<p>أكثر الأخطاء شيوعًا رفع صور بأبعاد أكبر بكثير من العرض. صورة 3000 بكسل معروضة بحجم 300 بكسل تهدر حجمًا دون فائدة.</p>\n<p>خطأ آخر أن تنسى التحميل الكسول للصور أسفل الصفحة. كل صورة تحمل فورًا تبطئ التحميل الأولي وتضر بـLCP.</p>\n<h2 id=\"priority-order\">ماذا تصلح أولًا؟ ترتيب الأولويات</h2>\n<p>ما الذي تصلحه أولًا؟ ابدأ بالصورة الرئيسية لأنها تحدد LCP، ثم حدد أبعاد كل الصور لإصلاح CLS، ثم قلّل الوزن الإجمالي لتحسين INP.</p>\n<p>هذا الترتيب يعطي أكبر تحسن بأقل جهد. إصلاح LCP وحده قد يرفع نتيجتك الإجمالية بشكل ملحوظ.</p>\n<h2 id=\"field-vs-lab\">بيانات الميدان مقابل بيانات المختبر</h2>\n<p>بيانات الميدان من زوار حقيقيين، وبيانات المختبر من اختبار محاكاة. جوجل تستخدم بيانات الميدان للترتيب، لذلك هي الأهم.</p>\n<p>استخدم بيانات المختبر للتشخيص السريع، وبيانات الميدان للحكم النهائي. إذا اختلفتا، فثق ببيانات الميدان.</p>\n<h2 id=\"lcp-images-vs-text\">عندما لا يكون عنصر LCP صورة</h2>\n<p>عندما لا يكون عنصر LCP صورة، فقد يكون عنوانًا نصيًا كبيرًا. في هذه الحالة، ركّز على سرعة الخادم والخطوط بدل الصور.</p>\n<p>لكن في معظم الصفحات، عنصر LCP صورة. تحقق من تقريرك لمعرفة عنصر LCP في صفحتك تحديدًا.</p>\n<h2 id=\"cls-fonts\">CLS ما وراء الصور: الخطوط والإعلانات</h2>\n<p>CLS لا يأتي من الصور وحدها: الخطوط التي تتغير عند التحميل والإعلانات التي تظهر متأخرة تحرك التخطيط أيضًا.</p>\n<p>احجز مساحة للخطوط والإعلانات كما تحجزها للصور. الثبات الكامل يحتاج إلى معالجة كل العناصر المتحركة.</p>\n<h2 id=\"inp-scripts\">INP والسكربتات الثقيلة</h2>\n<p>INP والسكربتات الثقيلة مرتبطان: سكربت طويل يحجب المتصفح فيتأخر الرد على النقر. الصور الثقيلة تزيد المشكلة سوءًا.</p>\n<p>قلّل السكربتات غير الضرورية وحسّن صورك معًا. الجمع بينهما يعطي أفضل نتيجة INP.</p>\n<h2 id=\"mobile-first\">الجوال أولًا: لماذا تهم نتائج الهاتف أكثر؟</h2>\n<p>الجوال أولًا: نتائج الهاتف أهم لأن معظم الزوار يأتون من الهواتف، ولأن جوجل تفهرس موقعك بنسخة الجوال.</p>\n<p>حسّن صورك للجوال أولًا: أبعاد أصغر وأحجام أقل. إذا كانت النتيجة جيدة على الجوال، فهي جيدة على الحاسوب غالبًا.</p>\n<h2 id=\"ongoing-monitoring\">المراقبة المستمرة لمؤشرات الويب الأساسية</h2>\n<p>المراقبة المستمرة لمؤشرات الويب الأساسية تعني فحصها شهريًا أو بعد أي تغيير كبير. التراجع الصامت يضر بترتيبك دون أن تلاحظ.</p>\n<p>استخدم Search Console للمراقبة التلقائية. تنبهك جوجل عندما تتراجع صفحاتك عن الحدود الجيدة.</p>\n<h2 id=\"final-check-cwv\">مراجعة أخيرة قبل النشر</h2>\n<p>قبل النشر، راجع كل صورة: مضغوطة، وبأبعاد صحيحة، وبتحميل كسول مناسب، وبنص بديل واضح.</p>\n<p>اختبر الصفحة بأداة قياس السرعة. وللتعمق، اقرأ <a href=\"/ar/blog/dalil-tahsin-suwar-al-web/\">الدليل الكامل لمحسّن صور الويب</a> و<a href=\"/ar/blog/kayfiyya-tahsin-as-suwar-li-surat-al-mawqi/\">كيفية تحسين الصور لسرعة الموقع</a>، أو جرّب <a href=\"/ar/daght-as-sura-ila-200kb/\">ضاغط 200 كيلوبايت</a> و<a href=\"/ar/daght-jumli-lis-suwar/\">ضاغط الصور بالجملة</a> لتحسين موقعك كاملًا.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"ما نتيجة LCP الجيدة؟","answer":"نتيجة LCP جيدة تعني أن أكبر عنصر في الصفحة يظهر خلال 2.5 ثانية. جوجل تعتبر أقل من 2.5 ثانية جيدًا، وبين 2.5 و4 ثوانٍ يحتاج تحسينًا."},{"question":"كيف تسبب الصور تغير التخطيط؟","answer":"عندما تحمل الصور دون أبعاد محددة، يقفز المحتوى عند ظهورها. حدد العرض والارتفاع في وسم الصورة، فيحجز المتصفح المساحة مسبقًا ولا يتحرك التخطيط."},{"question":"هل يحسّن التحميل الكسول مؤشرات الويب الأساسية؟","answer":"نعم، للصور أسفل الصفحة. التحميل الكسول يؤخر تحميلها حتى يقترب الزائر منها، فيسرّع التحميل الأولي ويحسّن النتائج."},{"question":"لماذا نتيجة LCP للجوال أسوأ من الحاسوب؟","answer":"لأن الهواتف أبطأ في المعالجة والشبكة. الصورة نفسها تستغرق وقتًا أطول على الجوال، لذلك ركّز على تحسين الصور للجوال أولًا."},{"question":"هل يمكن لتحسين الصور وحده إصلاح نتيجة مؤشرات ويب سيئة؟","answer":"غالبًا لا وحدها. الصور عامل كبير، لكن السكربتات الثقيلة والخطوط والخادم البطيء تؤثر أيضًا. ابدأ بالصور لأنها الأسهل والأسرع تأثيرًا."},{"question":"كم مرة يجب أن أراجع مؤشرات الويب الأساسية؟","answer":"راجعها شهريًا أو بعد أي تغيير كبير في موقعك. المراقبة الدورية تكشف التراجع قبل أن يؤثر في ترتيبك في محركات البحث."}];
